#include "../opponents/v88-radio-portal/forage.hpp"
#include <cassert>
#include <iostream>
using namespace unswbc;
int main(){Game board{20,15,64};Controller bot{2,Team::A,Direction::EAST,Vision{},64};game=&board;ct=&bot;std::vector<Tile> all;for(int y=0;y<15;++y)for(int x=0;x<20;++x)all.emplace_back(Position{x,y},std::nullopt,-1);bot.vision=Vision{all};bot.head.position={5,5};bot.length=2;bot.unit_count=5;strategy::Memory m;m.body={{5,5},{4,5}};m.observe_map(bot,100);std::vector<Tile> local;for(int y=2;y<=8;++y)for(int x=2;x<=8;++x)local.emplace_back(Position{x,y},std::nullopt,-1);bot.vision=Vision{local};const int cell=m.index({12,5});auto packet=[&](int round){return (std::uint64_t{0xA7}<<24)|(std::uint64_t(round)<<15)|(std::uint64_t(cell)<<3)|5;};forage::State s;assert(forage::select_goal(bot,m,s)==-1);bot.sonar_messages={packet(100)};assert(forage::select_goal(bot,m,s)==cell);assert(!m.cells[cell].pearl);bot.sonar_messages.clear();m.now=110;assert(forage::select_goal(bot,m,s)==-1);bot.sonar_messages={packet(111),12345};assert(forage::select_goal(bot,m,s)==-1);bot.sonar_messages={packet(110)};bot.vision=Vision{all};assert(forage::select_goal(bot,m,s)==-1);std::cout<<"Radio food hint expires, rejects future/malformed packets, and yields to visible empty tile.\n";}
